package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type AuditEntry struct {
	UserID    string `json:"user_id"`
	Action    string `json:"action"`
	Resource  string `json:"resource"`
	Timestamp string `json:"timestamp"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchAuditLogs allows operators to search audit entries
// Query parameter 'filter' supports field:value syntax
func searchAuditLogs(w http.ResponseWriter, r *http.Request) {
	apiKey := r.Header.Get("X-Service-Key")
	if apiKey == "" || !validateServiceKey(apiKey) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	filterParam := r.URL.Query().Get("filter")
	if filterParam == "" {
		http.Error(w, "filter parameter required", http.StatusBadRequest)
		return
	}

	// Parse filter - expected format: "field:value"
	parts := strings.SplitN(filterParam, ":", 2)
	if len(parts) != 2 {
		http.Error(w, "invalid filter format, use field:value", http.StatusBadRequest)
		return
	}

	fieldName := parts[0]
	fieldValue := parts[1]

	// Whitelist allowed fields
	allowedFields := map[string]bool{
		"user_id": true, "action": true, "resource": true, "timestamp": true,
	}
	if !allowedFields[fieldName] {
		http.Error(w, "invalid filter field", http.StatusBadRequest)
		return
	}

	// Build query - fieldName is validated above, fieldValue is user-controlled
	query := fmt.Sprintf("SELECT user_id, action, resource, timestamp FROM audit_log WHERE %s = '%s' ORDER BY timestamp DESC LIMIT 100", fieldName, fieldValue)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []AuditEntry
	for rows.Next() {
		var entry AuditEntry
		if err := rows.Scan(&entry.UserID, &entry.Action, &entry.Resource, &entry.Timestamp); err != nil {
			continue
		}
		results = append(results, entry)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func validateServiceKey(key string) bool {
	// In production, validates against HashiCorp Vault
	expected := os.Getenv("SERVICE_API_KEY")
	return key == expected
}

// healthCheck endpoint for LB probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/audit/search", searchAuditLogs)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("starting audit-query-service on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
